const puppeteer = require('puppeteer-core');

(async () => {
  try {
    const browser = await puppeteer.connect({
      browserURL: 'http://127.0.0.1:18789',
      defaultViewport: { width: 1280, height: 900 }
    });

    console.log("成功连接到Chrome浏览器");

    const page = await browser.newPage();

    console.log("正在打开网站...");
    await page.goto('https://gez.dongguanbank.cn/landlord/#/house/index', {
      waitUntil: 'networkidle0',
      timeout: 30000
    });

    function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }
    await sleep(2000);
    console.log("页面标题:", await page.title());
    console.log("当前URL:", page.url());

    await page.screenshot({ path: '/tmp/step1.png', fullPage: false });
    console.log("已保存step1截图");

    const loginFormInfo = await page.evaluate(() => {
      const inputs = document.querySelectorAll('input');
      const inputInfo = [];
      inputs.forEach((inp, i) => {
        inputInfo.push({
          index: i,
          type: inp.type,
          placeholder: inp.placeholder,
          name: inp.name,
          id: inp.id,
          class: inp.className.substring(0, 60)
        });
      });

      const buttons = document.querySelectorAll('button');
      const btnInfo = [];
      buttons.forEach((btn, i) => {
        btnInfo.push({
          index: i,
          text: btn.textContent.trim().substring(0, 50),
          class: btn.className.substring(0, 60),
          id: btn.id
        });
      });

      return { inputs: inputInfo, buttons: btnInfo };
    });

    console.log("输入框:", JSON.stringify(loginFormInfo.inputs, null, 2));
    console.log("按钮:", JSON.stringify(loginFormInfo.buttons, null, 2));

    // Fill login form
    const textInputs = await page.$$('input[type="text"], input:not([type="password"]):not([type="hidden"])');
    const passInputs = await page.$$('input[type="password"]');

    console.log(`找到 ${textInputs.length} 个文本输入框, ${passInputs.length} 个密码输入框`);

    if (textInputs.length > 0) {
      await textInputs[0].click();
      await textInputs[0].type('18122859721', { delay: 50 });
      console.log("已输入账号");
    }

    if (passInputs.length > 0) {
      await passInputs[0].click();
      await passInputs[0].type('100911yzp@', { delay: 50 });
      console.log("已输入密码");
    }

    // Click login button
    let loginClicked = false;
    for (const btn of loginFormInfo.buttons) {
      if (btn.text.includes('登录') || btn.text.includes('登 录')) {
        const btnEl = (await page.$$('button'))[btn.index];
        await btnEl.click();
        console.log("已点击登录按钮");
        loginClicked = true;
        break;
      }
    }

    if (!loginClicked) {
      // Try to find any div/button that might be the login trigger
      const loginTrigger = await page.evaluate(() => {
        const all = document.querySelectorAll('button, div[class*="btn"], div[class*="submit"], a[class*="btn"]');
        for (const el of all) {
          if (el.textContent.includes('登录')) return el.className;
        }
        return null;
      });
      console.log("备用登录查找:", loginTrigger);
    }

    await sleep(5000);

    await page.screenshot({ path: '/tmp/step2.png', fullPage: false });
    console.log("登录后URL:", page.url());

    const afterLoginInfo = await page.evaluate(() => {
      const allText = document.body.innerText;
      return {
        text: allText.substring(0, 2000),
        url: window.location.href,
        hasHouse: allText.includes('房源'),
        hasRent: allText.includes('到期') || allText.includes('租约')
      };
    });

    console.log("登录后页面文本:", afterLoginInfo.text);
    console.log("包含房源:", afterLoginInfo.hasHouse);

    // Try to find and click "房源" in the sidebar
    const sidebarElements = await page.evaluate(() => {
      const results = [];
      // Look for navigation/sidebar elements
      const navItems = document.querySelectorAll('.el-menu-item, .el-submenu, .sidebar-item, li, a, .nav-item, [class*="menu-item"], [class*="nav-item"]');
      navItems.forEach((item, i) => {
        const text = item.textContent.trim();
        if (text) {
          results.push({
            index: i,
            text: text.substring(0, 100),
            tag: item.tagName,
            class: item.className.substring(0, 80)
          });
        }
      });
      return results;
    });

    console.log("侧边栏元素:", JSON.stringify(sidebarElements, null, 2));

    // Try clicking 房源
    let houseClicked = false;
    for (const item of sidebarElements) {
      if (item.text === '房源' || item.text.startsWith('房源') || item.text.includes('房源管理')) {
        const elements = await page.$$('.el-menu-item, .el-submenu, .sidebar-item, li, a, .nav-item, [class*="menu-item"], [class*="nav-item"]');
        if (elements[item.index]) {
          await elements[item.index].click();
          console.log(`已点击: ${item.text}`);
          houseClicked = true;
          break;
        }
      }
    }

    if (!houseClicked) {
      // Try clicking by text content
      const anchors = await page.$$('a, button, span, div');
      for (const el of anchors) {
        const txt = await page.evaluate(el => el.textContent.trim(), el);
        if (txt === '房源' || txt.startsWith('房源')) {
          await el.click();
          console.log(`已点击房源元素: "${txt}"`);
          houseClicked = true;
          break;
        }
      }
    }

    await sleep(3000);
    await page.screenshot({ path: '/tmp/step3.png', fullPage: true });
    console.log("房源页URL:", page.url());

    // Get full page content
    const fullText = await page.evaluate(() => document.body.innerText);
    console.log("=== 完整页面文本 (前5000字) ===");
    console.log(fullText.substring(0, 5000));

    // Look for lease/expiry information
    const leaseInfo = await page.evaluate(() => {
      const text = document.body.innerText;
      // Search for lease-related terms
      const lines = text.split('\n').filter(l => 
        l.includes('到期') || l.includes('租约') || l.includes('租期') || 
        l.includes('即将') || l.includes('房号') || l.includes('房间') ||
        l.includes('合同') || l.includes('结束') || l.includes('截止')
      );
      return lines;
    });

    console.log("=== 租约相关行 ===");
    console.log(leaseInfo.join('\n'));

    // Also look at tables
    const tableInfo = await page.evaluate(() => {
      const tables = document.querySelectorAll('table, .el-table, [class*="table"], [class*="grid"]');
      const info = [];
      tables.forEach((t, i) => {
        info.push(`表格${i}: ${t.tagName} rows=${t.querySelectorAll('tr').length}`);
      });
      return info.length > 0 ? info : '未找到表格';
    });
    console.log("表格信息:", tableInfo);

    await browser.close();
    console.log("完成");
  } catch (err) {
    console.error("错误:", err.message);
    process.exit(1);
  }
})();

